use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},io::{Read,BufRead,BufReader},process::{Command,Stdio},collections::{BTreeMap,BTreeSet}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-coordinate-leaf-profile177";
const REF:&str="/home/ubuntu/src/zopro-perf-work/busy-reset-sdk176/sdk-ON";
const SEED:&str="/home/ubuntu/src/zopro-perf-work/g2-coordinate-leaf177/proof-sha256-after-main.json";
const VERIFY:&str="/home/ubuntu/src/zopro-perf-work/batch-local-steal/gnark/verify";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(n:&str,v:&Value){fs::write(r(n),serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn receipt(folder:&str,s:&Value){let base=r(format!("{folder}/{}",s["name"].as_str().unwrap()));let e=read(base.join("exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for st in["stdout","stderr"]{assert_eq!(hash(base.join(format!("{st}.log"))),e[format!("{st}_sha256")]);}let c=read(base.join("command.json"));assert_eq!(&c["argv"].as_array().unwrap()[4..],s["argv"].as_array().unwrap());for(k,v)in s["environment"].as_object().into_iter().flatten(){if !k.starts_with("CARGO_"){assert_eq!(c["environment"][k],*v);}}}
fn sdk(folder:&str,j:&Value)->(Vec<u64>,Value){let text=fs::read_to_string(r(format!("{folder}/{}/stdout.log",j["name"].as_str().unwrap()))).unwrap();let samples=text.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).enumerate().map(|(i,l)|{let v:Value=serde_json::from_str(l).unwrap();assert_eq!(v["round"],i);let ms=v["ms"].as_f64().unwrap();assert!(ms.is_finite()&&ms>0.);(ms*1e6).round()as u64}).collect::<Vec<_>>();assert_eq!(samples.len() as u64,j["rounds"].as_u64().unwrap());let summaries=text.lines().filter_map(|l|l.strip_prefix("SUMMARY ")).collect::<Vec<_>>();assert_eq!(summaries.len(),1);let summary:Value=serde_json::from_str(summaries[0]).unwrap();assert_eq!(summary["rounds"],j["rounds"]);assert_eq!(summary["priming"],3);assert_eq!(summary["workers"],j["case"]["workers"]);assert_eq!(summary["placement_before"],summary["placement_after"]);let p=&summary["placement_before"];assert_eq!(p["mode"],"fixed");let workers=p["workers"].as_u64().unwrap();assert_eq!(p["tasks"],workers+1);let mut tids=BTreeSet::new();assert_eq!(p["worker_rows"].as_array().unwrap().len()as u64,workers);for(i,w)in p["worker_rows"].as_array().unwrap().iter().enumerate(){assert_eq!(w["index"],i);assert_eq!(w["allowed"],json!([if workers==1{2}else{i}]));assert!(tids.insert(w["tid"].as_u64().unwrap()));}(samples,summary)}
fn proof(folder:&str,j:&Value,ledger:&mut BTreeSet<String>)->Value{let name=j["name"].as_str().unwrap();let dir=j["proof_dir"].as_str().unwrap();let file=format!("{dir}/0.proof");assert_eq!(fs::metadata(&file).unwrap().len(),164);let ph=hash(&file);let pu=hash(format!("{dir}/0.public"));assert_eq!(pu,j["case"]["public_sha256"]);let text=fs::read_to_string(r(format!("{folder}/verify-{name}/stdout.log"))).unwrap();for needle in[format!("proof_sha256={ph}"),format!("public_sha256={pu}"),format!("image_sha256={}",j["case"]["image_sha256"].as_str().unwrap())]{assert!(text.contains(&needle));}assert!(ledger.insert(ph.clone()),"fresh proof {name}");json!({"name":name,"proof_sha256":ph,"public_sha256":pu,"image_sha256":j["case"]["image_sha256"],"independent_Gnark_verified":true})}

include!("sampling.rs");include!("metadata.rs");include!("counter.rs");
fn diagnostics(folder:&str,j:&Value,summary:&Value)->Option<Value>{let panel=j["panel"].as_str().unwrap();let name=j["name"].as_str().unwrap();let rounds=j["rounds"].as_f64().unwrap();if panel=="stat"{let events=fs::read_to_string(j["data"].as_str().unwrap()).unwrap().lines().filter_map(event_line).collect::<BTreeMap<_,_>>();let quality=events.len()==4&&["cycles:u","instructions:u","cache-misses:u","branch-misses:u"].iter().all(|k|events.get(*k).is_some_and(|v|v["qualified"]==true&&v["running_percent"].as_f64().is_some_and(|p|p>=99.9)));let per=events.iter().map(|(k,v)|(k.clone(),v["count"].as_f64().map(|c|c/rounds))).collect::<BTreeMap<_,_>>();return Some(json!({"qualified":quality,"events":events,"per_proof":per}));}
if panel=="cycles"{let attrs=fs::read_to_string(r(format!("{folder}/events-{name}/stdout.log"))).unwrap();for n in["cycles:u","16000000","CPU","TIME","PERIOD"]{assert!(attrs.contains(n));}assert!(!attrs.contains("freq: 1"));let meta=fs::read_to_string(r(format!("{folder}/metadata-{name}/stdout.log"))).unwrap();let(pid,allowed)=profile_owners(&meta,j["binary"].as_str().unwrap());let p=&summary["placement_before"];let workers=p["worker_rows"].as_array().unwrap().iter().map(|w|(w["tid"].as_u64().unwrap()as u32,w["allowed"][0].as_u64().unwrap()as u32)).collect::<BTreeMap<_,_>>();assert!(workers.keys().all(|t|allowed.contains(t)));let main=p["main_allowed"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u32).collect::<BTreeSet<_>>();let mut count=0u64;let mut unknown=0;let mut symbols=BTreeMap::<String,u64>::new();let mut tids=BTreeSet::new();for(proc,tid,cpu,period,sym)in fs::read_to_string(r(format!("{folder}/decode-{name}/stdout.log"))).unwrap().lines().filter_map(sample){assert_eq!(proc,pid);assert!(allowed.contains(&tid));assert_eq!(period,16000000);if let Some(c)=workers.get(&tid){assert_eq!(cpu,*c);}else{assert_eq!(tid,pid);assert!(main.contains(&cpu));}count+=1;unknown+=u64::from(sym.starts_with("[unknown]"));*symbols.entry(sym).or_default()+=1;tids.insert(tid);}let loss=read(r(format!("{folder}/loss-{name}/stdout.log")));let fraction=unknown as f64/count.max(1)as f64;let mut list=symbols.into_iter().map(|(symbol,n)|json!({"symbol":symbol,"samples":n,"share":n as f64/count.max(1)as f64})).collect::<Vec<_>>();list.sort_by_key(|v|std::cmp::Reverse(v["samples"].as_u64().unwrap()));return Some(json!({"qualified":count>=1000&&fraction<=0.05&&loss["zero_lost"]==true,"samples":count,"unknown_share":fraction,"zero_lost":loss["zero_lost"],"period":16000000,"actual_PID":pid,"sampled_TIDs":tids,"assigned_PID_TID_CPU_and_MMAP":true,"perf_data_sha256":hash(j["data"].as_str().unwrap()),"absolute_period_coverage_unvalidated":true,"symbols":list}));}None}
